  "engram/context.py": "\"\"\"context - the shared memory backend. engram_id=\"ctx\" is the wire address.\n\nSame Engram API, three backends - swap the constructor only:\n    from cosmonapse import SqliteEngram, PostgresEngram\n    SqliteEngram(engram_id=\"ctx\", engram_kind=\"context\", path=\"./engram.db\")\n    PostgresEngram(engram_id=\"ctx\", engram_kind=\"context\",\n                   dsn=\"postgresql://user:pass@localhost/cosmo\")\n\nimprint ops:  add | append | merge | upsert | delete  (merge/upsert take merge_key)\nrecall modes: first | merge | all\n  (set the default via EngramBinding(..., default_recall_mode=\"merge\"))\n\"\"\"\nfrom cosmonapse import InMemoryEngram\n\nENGRAM = InMemoryEngram(engram_id=\"ctx\", engram_kind=\"context\")\n",
  "neurons/researcher.py": "\"\"\"researcher - a Neuron with recall/imprint injected by its Axon.\n\nThe Neuron gains two keyword-only parameters: recall and imprint.\nThe Axon injects them at call time because it was constructed with\nengrams=[EngramBinding(...)]. Under the hood recall(\"ctx\", ...) emits\na RECALL Signal under the current trace_id and awaits the matching\nRECALLED reply - the Neuron stays pure.\n\"\"\"\nfrom cosmonapse import Axon, EngramBinding\n\n\nasync def researcher(input, context, *, recall, imprint):\n    question = input[\"question\"]\n    key = f\"q:{question}\"\n\n    # 1. Look in shared memory for a prior answer to this exact question.\n    prior = await recall(\"ctx\", query={\"merge_key\": key})\n    if prior.hits:\n        cached = prior.hits[0].entry[\"content\"][\"answer\"]\n        return {\"answer\": cached, \"source\": \"cache\"}\n\n    # 2. Compute a \"fresh\" answer (stubbed for the demo).\n    answer = f\"Answer to {question!r}: 42\"\n\n    # 3. Write it back so the next call hits the cache. merge_key dedupes by\n    #    question, so repeated imprints upsert a single entry.\n    await imprint(\n        \"ctx\",\n        op=\"upsert\",\n        entry={\"content\": {\"question\": question, \"answer\": answer},\n               \"tags\": [\"qa\"]},\n        merge_key=key,\n        await_ack=True,\n        deadline_ms=500,\n    )\n    return {\"answer\": answer, \"source\": \"computed\"}\n\n\n# The binding maps a local name (\"ctx\") to the wire engram_id\n# (directed_id), so the Neuron addresses memory by a stable local name -\n# ops can repoint the backend without editing Neuron code.\nAXON = Axon(\n    neuron_id=\"researcher\",\n    neuron_fn=researcher,\n    capabilities=[\"research\"],\n    engrams=[EngramBinding(name=\"ctx\", directed_id=\"ctx\")],\n)\n",
